import"./hoisted.CaTDiaTo.js";const n=document.querySelectorAll(".fade-section"),r=new IntersectionObserver(e=>{e.forEach(t=>{t.isIntersecting&&(t.target.classList.add("fade-in-active"),r.unobserve(t.target))})},{threshold:.1,rootMargin:"0px 0px -40px 0px"});n.forEach(e=>r.observe(e));const o=document.getElementById("hero");window.addEventListener("scroll",()=>{if(!o)return;const e=window.scrollY,t=o.offsetHeight,s=Math.min(e/t,1);o.style.opacity=String(1-s*1.2)},{passive:!0});
